#include <stdio.h>
int main(){
  int n, x, i, cnt = 0; double sum = 0;
  scanf("%d", &n);
  for (i = 0; i < n; i++){
    scanf("%d", &x);
    sum += x;
    if (x >= 60) cnt++;
  }
  if (n == 0) printf("average = 0.0\ncount = 0\n");
  else printf("average = %.1f\ncount = %d\n", sum / n, cnt);
  return 0;
}

#include <stdio.h>
int main(){
  double x, term = 1, sum = 0;
  int i = 0;
  scanf("%lf", &x);
  while (term >= 1e-5 || term <= -1e-5){
    sum += term;
    i++;
    term = term * x / i;   // 递推：term_k = term_{k-1} * x / k
  }
  sum += term;  // 补上最后一项（绝对值 < 1e-5 但仍计入？按题意取整项和）
  printf("sum = %.6f\n", sum);
  return 0;
}

#include <stdio.h>
int main(){
  int n, i, t, d, sum;
  int pw[10];
  long long start = 1, end = 10, k;
  scanf("%d", &n);
  for (i = 0; i < n - 1; i++) start *= 10;
  for (i = 0; i < n; i++) end *= 10;
  for (i = 0; i < 10; i++){
    pw[i] = 1;
    for (d = 0; d < n; d++) pw[i] *= i;   // 预计算 0..9 的 n 次方
  }
  for (k = start; k < end; k++){
    t = (int)k; sum = 0;
    while (t){ sum += pw[t % 10]; t /= 10; }
    if (sum == k) printf("%d\n", (int)k);
  }
  return 0;
}

#include <stdio.h>
int sum(int m, int n){
  int s = 0, i;
  for (i = m; i <= n; i++) s += i;
  return s;
}
int main(){
  int m, n;
  scanf("%d %d", &m, &n);
  printf("sum = %d\n", sum(m, n));
  return 0;
}

#include <stdio.h>
long long fib(int n){
  long long a = 1, b = 1, c, i;
  if (n == 1 || n == 2) return 1;
  for (i = 3; i <= n; i++){ c = a + b; a = b; b = c; }
  return b;
}
int main(){
  int m, n, k, found = 0;
  scanf("%d %d", &m, &n);
  for (k = 1; fib(k) <= n; k++){
    if (fib(k) >= m){ printf("%lld\n", fib(k)); found = 1; }
  }
  if (!found) printf("None\n");
  return 0;
}

#include <stdio.h>
int main(){
  int n, x, i, cnt[10] = {0}, max = 0;
  scanf("%d", &n);
  for (i = 0; i < n; i++){
    scanf("%d", &x);
    cnt[x % 10]++;
  }
  for (i = 0; i < 10; i++) if (cnt[i] > max) max = cnt[i];
  for (i = 0; i < 10; i++) if (cnt[i] == max) printf("%d: %d\n", i, max);
  return 0;
}
